/* ============================================
   Mark'd Website - Utility Functions
   ============================================ */

(function() {
    'use strict';

    /**
     * Debounce function - delays function execution
     * @param {Function} func - Function to debounce
     * @param {number} wait - Wait time in milliseconds
     * @returns {Function} Debounced function
     */
    function debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
            const later = () => {
                clearTimeout(timeout);
                func(...args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
        };
    }

    /**
     * Throttle function - limits function execution rate
     * @param {Function} func - Function to throttle
     * @param {number} limit - Time limit in milliseconds
     * @returns {Function} Throttled function
     */
    function throttle(func, limit) {
        let inThrottle;
        return function executedFunction(...args) {
            if (!inThrottle) {
                func.apply(this, args);
                inThrottle = true;
                setTimeout(() => inThrottle = false, limit);
            }
        };
    }

    /**
     * Check if element is in viewport
     * @param {Element} element - DOM element
     * @param {number} threshold - Threshold percentage (0-1)
     * @returns {boolean} True if element is in viewport
     */
    function isInViewport(element, threshold = 0) {
        if (!element) return false;
        
        const rect = element.getBoundingClientRect();
        const windowHeight = window.innerHeight || document.documentElement.clientHeight;
        const windowWidth = window.innerWidth || document.documentElement.clientWidth;
        
        const verticalVisible = rect.top < windowHeight * (1 - threshold) && rect.bottom > windowHeight * threshold;
        const horizontalVisible = rect.left < windowWidth * (1 - threshold) && rect.right > windowWidth * threshold;
        
        return verticalVisible && horizontalVisible;
    }

    /**
     * Wait for element to appear in DOM
     * @param {string} selector - CSS selector
     * @param {number} timeout - Timeout in milliseconds
     * @returns {Promise<Element>} Element when found
     */
    function waitForElement(selector, timeout = 5000) {
        return new Promise((resolve, reject) => {
            const element = document.querySelector(selector);
            if (element) {
                resolve(element);
                return;
            }

            const observer = new MutationObserver((mutations, obs) => {
                const element = document.querySelector(selector);
                if (element) {
                    obs.disconnect();
                    resolve(element);
                }
            });

            observer.observe(document.body, {
                childList: true,
                subtree: true
            });

            setTimeout(() => {
                observer.disconnect();
                reject(new Error(`Element "${selector}" not found within ${timeout}ms`));
            }, timeout);
        });
    }

    /**
     * Get nested object value by path
     * @param {Object} obj - Object to search
     * @param {string} path - Dot-separated path (e.g., "user.profile.name")
     * @param {*} defaultValue - Default value if not found
     * @returns {*} Value at path or default value
     */
    function getNestedValue(obj, path, defaultValue = undefined) {
        const keys = path.split('.');
        let result = obj;
        
        for (const key of keys) {
            if (result === null || result === undefined || typeof result !== 'object') {
                return defaultValue;
            }
            result = result[key];
        }
        
        return result !== undefined ? result : defaultValue;
    }

    /**
     * Set nested object value by path
     * @param {Object} obj - Object to modify
     * @param {string} path - Dot-separated path
     * @param {*} value - Value to set
     */
    function setNestedValue(obj, path, value) {
        const keys = path.split('.');
        const lastKey = keys.pop();
        let current = obj;
        
        for (const key of keys) {
            if (!(key in current) || typeof current[key] !== 'object') {
                current[key] = {};
            }
            current = current[key];
        }
        
        current[lastKey] = value;
    }

    /**
     * Check if browser supports feature
     * @param {string} feature - Feature to check (e.g., "IntersectionObserver", "localStorage")
     * @returns {boolean} True if feature is supported
     */
    function supportsFeature(feature) {
        const features = {
            'IntersectionObserver': () => 'IntersectionObserver' in window,
            'localStorage': () => {
                try {
                    const test = '__localStorage_test__';
                    localStorage.setItem(test, test);
                    localStorage.removeItem(test);
                    return true;
                } catch {
                    return false;
                }
            },
            'sessionStorage': () => {
                try {
                    const test = '__sessionStorage_test__';
                    sessionStorage.setItem(test, test);
                    sessionStorage.removeItem(test);
                    return true;
                } catch {
                    return false;
                }
            }
        };

        const check = features[feature];
        return check ? check() : false;
    }

    /**
     * Safe JSON parse
     * @param {string} str - JSON string
     * @param {*} defaultValue - Default value if parse fails
     * @returns {*} Parsed value or default
     */
    function safeJsonParse(str, defaultValue = null) {
        try {
            return JSON.parse(str);
        } catch {
            return defaultValue;
        }
    }

    /**
     * Get URL parameter
     * @param {string} name - Parameter name
     * @param {string} url - URL (optional, defaults to current URL)
     * @returns {string|null} Parameter value or null
     */
    function getUrlParameter(name, url = window.location.href) {
        const urlObj = new URL(url);
        return urlObj.searchParams.get(name);
    }

    /**
     * Format file size
     * @param {number} bytes - Size in bytes
     * @returns {string} Formatted size
     */
    function formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
    }

    // Export to global namespace
    if (typeof window !== 'undefined') {
        window.MarkdUtils = {
            debounce,
            throttle,
            isInViewport,
            waitForElement,
            getNestedValue,
            setNestedValue,
            supportsFeature,
            safeJsonParse,
            getUrlParameter,
            formatFileSize
        };
    }
})();







/* === assets/js/performance.js === */
/* ============================================
   Mark'd Website - Performance Monitoring
   ============================================ */

(function() {
    'use strict';

    const metrics = {
        pageLoadTime: 0,
        domContentLoaded: 0,
        firstPaint: 0,
        firstContentfulPaint: 0,
        timeToInteractive: 0
    };

    /**
     * Measure page load performance
     */
    function measurePerformance() {
        if (!window.performance || !window.performance.timing) {
            console.warn('Performance API not available');
            return;
        }

        const timing = window.performance.timing;
        const navigation = window.performance.navigation;

        // Page load time
        metrics.pageLoadTime = timing.loadEventEnd - timing.navigationStart;
        metrics.domContentLoaded = timing.domContentLoadedEventEnd - timing.navigationStart;

        // Log metrics (only in development)
        if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
            console.log('Performance Metrics:', {
                pageLoadTime: metrics.pageLoadTime + 'ms',
                domContentLoaded: metrics.domContentLoaded + 'ms',
                navigationType: navigation.type === 0 ? 'navigate' : 
                               navigation.type === 1 ? 'reload' : 
                               navigation.type === 2 ? 'back_forward' : 'other'
            });
        }

        // Check for performance issues
        if (metrics.pageLoadTime > 3000) {
            console.warn('Page load time is slow:', metrics.pageLoadTime + 'ms');
        }
    }

    /**
     * Measure paint timing (if available)
     */
    function measurePaintTiming() {
        if (!window.performance || !window.performance.getEntriesByType) {
            return;
        }

        try {
            const paintEntries = window.performance.getEntriesByType('paint');
            
            paintEntries.forEach(entry => {
                if (entry.name === 'first-paint') {
                    metrics.firstPaint = entry.startTime;
                } else if (entry.name === 'first-contentful-paint') {
                    metrics.firstContentfulPaint = entry.startTime;
                }
            });

            if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
                if (metrics.firstPaint) {
                    console.log('First Paint:', metrics.firstPaint.toFixed(2) + 'ms');
                }
                if (metrics.firstContentfulPaint) {
                    console.log('First Contentful Paint:', metrics.firstContentfulPaint.toFixed(2) + 'ms');
                }
            }
        } catch (e) {
            // Paint Timing API not supported
        }
    }

    /**
     * Measure resource loading
     */
    function measureResourceLoading() {
        if (!window.performance || !window.performance.getEntriesByType) {
            return;
        }

        try {
            const resources = window.performance.getEntriesByType('resource');
            const slowResources = resources.filter(resource => resource.duration > 1000);
            
            if (slowResources.length > 0 && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1')) {
                console.warn('Slow resources detected:', slowResources.map(r => ({
                    name: r.name.split('/').pop(),
                    duration: r.duration.toFixed(2) + 'ms'
                })));
            }
        } catch (e) {
            // Resource Timing API not fully supported
        }
    }

    /**
     * Get performance metrics
     * @returns {Object} Performance metrics
     */
    function getMetrics() {
        return { ...metrics };
    }

    /**
     * Initialize performance monitoring
     */
    function init() {
        // Measure when page loads
        if (document.readyState === 'complete') {
            measurePerformance();
            measurePaintTiming();
            measureResourceLoading();
        } else {
            window.addEventListener('load', () => {
                measurePerformance();
                measurePaintTiming();
                measureResourceLoading();
            });
        }

        // Measure paint timing (may be available earlier)
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', measurePaintTiming);
        } else {
            measurePaintTiming();
        }
    }

    // Initialize
    init();

    // Export to global namespace
    if (typeof window !== 'undefined') {
        window.MarkdPerformance = {
            init,
            getMetrics,
            measurePerformance,
            measurePaintTiming,
            measureResourceLoading
        };
    }
})();







